general='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]: positions.setdefault(grid[r][c], []).append((r,c))
    boxes=[]
    for color, pts in positions.items():
        r1=min(r for r,c in pts); r2=max(r for r,c in pts)
        c1=min(c for r,c in pts); c2=max(c for r,c in pts)
        if r2-r1<2 or c2-c1<2: continue
        perimeter={(r,c) for r in range(r1,r2+1) for c in range(c1,c2+1) if r in (r1,r2) or c in (c1,c2)}
        if all(grid[r][c]==color for r,c in perimeter) and all(grid[r][c] in (0,color) for r in range(r1+1,r2) for c in range(c1+1,c2)):
            boxes.append((r1,c1,r2,c2,color))
    framed={(r,c) for r1,c1,r2,c2,col in boxes for r in range(r1,r2+1) for c in range(c1,c2+1)}
    counts=Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] and (r,c) not in framed)
    noises=[col for col,n in counts.most_common()]
    boxes.sort(key=lambda b:(b[2]-b[0]-1)*(b[3]-b[1]-1))
    noises.sort(key=lambda col:(counts[col],col))
    out=[[0]*w for _ in range(h)]
    for (r1,c1,r2,c2,border), fill in zip(boxes,noises):
        for r in range(r1,r2+1):
            for c in range(c1,c2+1):
                if r in (r1,r2) or c in (c1,c2): out[r][c]=border
                elif (r-r1+c-c1)%2==0: out[r][c]=fill
    return out
'''
